mapper.select:
SELECT D.ACCT_SUBJECT_ID fundId, BASI.ACCT_SUBJECT_NAME finprodName, E.SUBJECT_NO fAcctCode, E.SUBJECT_NAME fAcctname, E.SUBJECT_LEVEL fAcctLevel, E.FSUBJECT_ID fAcctParent, CASE WHEN E.SUBJECT_LEVEL IN ('1', '2') THEN 0 WHEN E.SUBJECT_LEVEL = '3' THEN CASE WHEN E.GEN_DETSUB_FLAG = 'Y' THEN 0 ELSE 1 END WHEN E.SUBJECT_LEVEL = '4' THEN 1 END fAcctDetail, CASE WHEN E.SUBJECT_TYPE = #{SUBJECT_TYPE_01} THEN 1 /** [数据字典.科目类型_资产类] **/ WHEN E.SUBJECT_TYPE = #{SUBJECT_TYPE_02} THEN 2 /** [数据字典.科目类型_负债类] **/ WHEN E.SUBJECT_TYPE = #{SUBJECT_TYPE_03} THEN 3 /** [数据字典.科目类型_资产负债共同类] **/ WHEN E.SUBJECT_TYPE = #{SUBJECT_TYPE_04} THEN 4 /** [数据字典.科目类型_所有者权益类] **/ WHEN E.SUBJECT_TYPE = #{SUBJECT_TYPE_05} THEN 5 END fAcctClass, /** [数据字典.科目类型_损益类] **/ CASE WHEN E.BAL_FLAG = 'C' THEN -1 WHEN E.BAL_FLAG = 'D' THEN 1 ELSE 0 END fbaldc, DECODE(SIV.XML_STATUS, NULL, 0, SIV.XML_STATUS) xmlStatus FROM ( SELECT A.BOOKSET_ID, A.SUBJECT_NO, A.SUBJECT_NAME, A.SUBJECT_LEVEL, A.FSUBJECT_ID, A.GEN_DETSUB_FLAG, A.SUBJECT_TYPE, A.BAL_FLAG FROM BOK_SUBJECT A
UNION SELECT bb.bookset_id_tmpl, B.DETAIL_SUBJECT_NO SUBJECT_NO, B.DETAIL_SUBJECT_NAME SUBJECT_NAME, 4 SUBJECT_LEVEL, B.FSUBJECT_ID, 'N' GEN_DETSUB_FLAG, C.SUBJECT_TYPE, C.BAL_FLAG FROM BOK_BUSS_DETSUB B inner join bok_bookset bb on bb.bookset_id = b.bookset_id LEFT JOIN BOK_SUBJECT C ON B.FSUBJECT_ID = C.SUBJECT_NO AND bb.bookset_id_tmpl = C.BOOKSET_ID
) E INNER JOIN BOK_BOOKSET D ON E.BOOKSET_ID = D.BOOKSET_ID_TMPL LEFT JOIN BOK_ACCT_SUBJECT_INFO BASI ON D.ACCT_SUBJECT_ID = BASI.ACCT_SUBJECT_ID AND BASI.ACCT_SUBJECT_TYPE = D.ACCT_SUBJECT_TYPE LEFT JOIN SZT_INTERF_VALUATION SIV ON SIV.FINPROD_ID = D.ACCT_SUBJECT_ID AND SIV.INTER_TYPE = #{interType} /** [数据字典.深证通接口类型.科目信息表] **/ /**E.SUBJECT_TYPE IN ([数据字典.科目类型_资产类], [数据字典.科目类型_负债类], [数据字典.科目类型_资产负债共同类], [数据字典.科目类型_所有者权益类], [数据字典.科目类型_损益类])**/ WHERE D.ACCT_SUBJECT_ID = #{prodId}
#{item,jdbcType=VARCHAR}
